```javascript
function check(id, status, details = {}) {
  return { id, status, ...details };
}

function sortByIdByteOrder(array, idKey = 'id') {
  return [...array].sort((a, b) => {
    const valA = String(a[idKey] ?? '');
    const valB = String(b[idKey] ?? '');
    if (valA < valB) return -1;
    if (valA > valB) return 1;
    return 0;
  });
}
```

