![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

To prevent diff churn and avoid role-first drift, sort artifact receipt arrays lexicographically by UTF-8 byte-order path first, and then by role.

```javascript
function sourceArtifactReceipts(root, paths) {
  const receipts = [ 
    artifactReceipt(root, 'figureasset_vlm_wave1_candidate_bbox_proposals', paths.candidateBboxIn),
    artifactReceipt(root, 'figureasset_wave1_precise_source_crops', paths.preciseCropsIn),
    artifactReceipt(root, 'figureasset_precise_crop_source_map', paths.sourceMapIn),
  ];
  return [...receipts].sort((a, b) => {
    const pathA = String(a.path ?? '');
    const pathB = String(b.path ?? '');
    if (pathA !== pathB) return pathA < pathB ? -1 : 1;
    const roleA = String(a.role ?? '');
    const roleB = String(b.role ?? '');
    return roleA < roleB ? -1 : roleA > roleB ? 1 : 0;
  });
}
```

