+    code: 'visual_class_mismatch_missing_expected_region',
+    category: 'missing_diagram_or_table_region',
+    severity: 'manual_crop',
+    message: 'Existing VLM signal class does not match the source-map expected visual class.',
+    action: 'Manual crop review should include the expected diagram/table region from the source page.',
+    evidence: {
+      expected_visual_classes: [...expected],
+      actual_visual_object_class: actualClass,
+      visual_required_reason: sourceMapRow?.visual_required_reason ?? null,
+    },
+  })];
+}
+
+function multiFigureReviewBlockers({ cropArtifacts, sourceMapRow, candidateRow }) {
+  const blockers = [];
+  const plannedScope = sourceMapRow?.planned_crop_scope ?? null;
+  const bboxCandidateCount = asArray(candidateRow?.bbox_candidates).length;
+  if (cropArtifacts.length > 1 || bboxCandidateCount > 1) {
+    blockers.push(blocker({
+      code: 'multi_figure_ambiguity',
+      category: 'multi_figure_ambiguity',
+      severity: 'human_review',
+      message: 'Multiple crop candidates exist for one Wave 1 row; deterministic QA cannot confirm whether they are independent visuals or one incomplete visual split.',
+      action: 'Human visual review should decide whether to accept all crop parts, merge them, or request a manual crop.',
+      evidence: {
+        crop_artifact_count: cropArtifacts.length,
+        bbox_candidate_count: bboxCandidateCount,
+        planned_crop_scope: plannedScope,
+      },
+    }));
+  } else if (plannedScope === 'multi_visual' || plannedScope === 'layout_fragment_candidate') {
+    blockers.push(blocker({
+      code: 'planned_multi_visual_scope_requires_review',
+      category: 'multi_figure_ambiguity',
+      severity: 'human_review',
+      message: 'Source map planned scope marks the row as multi-visual or layout-fragment candidate.',
+      action: 'Human visual review should confirm that the produced crop covers all required visual regions.',
+      evidence: {
+        planned_crop_scope: plannedScope,
+        crop_artifact_count: cropArtifacts.length,
+      },
+    }));
+  }
+  return blockers;
+}
+
+function choosePosture(blockers) {
+  if (blockers.some((item) => item.severity === 'manual_crop')) return 'needs_manual_crop';
+  if (blockers.some((item) => item.severity === 'human_review')) return 'needs_human_visual_review';
+  return 'visual_qa_accepted';
+}
+
+async function buildQaRow({ root, paths, candidateEntry, cropEntries, manualEntries, sourceMapEntry, thresholds }) {
+  const candidateRow = candidateEntry.row;
+  const cropArtifacts = cropEntries.map((entry) => entry.row);
+  const sourceMapRow = sourceMapEntry?.row ?? null;
+  const deterministicChecks = [];
+  const cropImageMetrics = [];
+  const blockers = [];
+
+  if (!sourceMapRow) {
+    blockers.push(blocker({
+      code: 'source_map_row_missing',
+      category: 'wrong_page_or_source_linkage',
+      severity: 'human_review',
+      message: 'Wave 1 candidate row has no matching precise crop source-map row.',
+      action: 'Reconcile Wave 1 row linkage before crop acceptance.',
+      evidence: {
+        precise_crop_source_map_row_id: candidateRow.precise_crop_source_map_row_id ?? null,
+      },
+    }));
+    deterministicChecks.push(check('source_map_row_linked', 'fail'));
+  } else {
+    deterministicChecks.push(check('source_map_row_linked', 'pass', {
+      source_map_index: sourceMapEntry.index,
+      planned_crop_scope: sourceMapRow.planned_crop_scope ?? null,
+    }));
+  }
+
+  blockers.push(...manualBlockers(manualEntries));
+  blockers.push(...classMismatchBlockers({ candidateRow, sourceMapRow }));
+  blockers.push(...multiFigureReviewBlockers({ cropArtifacts, sourceMapRow, candidateRow }));
+
+  if (cropArtifacts.length === 0) {
+    deterministicChecks.push(check('crop_artifact_present', 'fail', {
+      manual_review_entry_count: manualEntries.length,
+    }));
+    if (manualEntries.length === 0) {
+      blockers.push(blocker({
+        code: 'crop_artifact_missing_without_manual_review_row',
+        category: 'crop_integrity',
+        severity: 'manual_crop',
+        message: 'No produced crop artifact and no precise-crop manual-review row exists for this Wave 1 row.',
+        action: 'Create a manual crop or add a review row explaining why no crop exists.',
+        evidence: {
+          precise_crop_source_map_row_id: candidateRow.precise_crop_source_map_row_id ?? null,
+        },
+      }));
+    }
+  } else {
+    deterministicChecks.push(check('crop_artifact_present', 'pass', {
+      crop_artifact_count: cropArtifacts.length,
+    }));
+  }
+
+  for (const cropArtifact of cropArtifacts) {
+    const sourceMatch = sourcePageMatches(cropArtifact, sourceMapRow);
+    if (sourceMatch.status === 'pass') {
+      deterministicChecks.push(check('source_page_matches_candidate', 'pass', {
+        crop_artifact_id: cropArtifact.crop_artifact_id,
+        ...sourceMatch.details,
+      }));
+    } else if (sourceMatch.status === 'review') {
+      deterministicChecks.push(check('source_page_matches_candidate', 'review', {
+        crop_artifact_id: cropArtifact.crop_artifact_id,
+        ...sourceMatch.details,
+      }));
+      blockers.push(blocker({
+        code: 'source_page_candidates_missing_for_wrong_page_check',
+        category: 'wrong_page_or_source_linkage',
+        severity: 'human_review',
+        message: 'Cannot deterministically confirm whether crop came from an expected source page.',
+        action: 'Human review should verify source-page linkage before acceptance.',
+        evidence: sourceMatch.details,
+      }));
+    } else {
+      deterministicChecks.push(check('source_page_matches_candidate', 'fail', {
+        crop_artifact_id: cropArtifact.crop_artifact_id,
+        ...sourceMatch.details,
+      }));
+      blockers.push(blocker({
+        code: 'source_page_mismatch_wrong_page',
+        category: 'wrong_page_crop',
+        severity: 'manual_crop',
+        message: 'Crop source page does not match the source-map candidate page.',
+        action: 'Manual crop from the correct source-map page candidate.',
+        evidence: sourceMatch.details,
+      }));
+    }
+
+    const analysis = await analyzeCropImage(root, cropArtifact, thresholds);
+    deterministicChecks.push(...analysis.checks.map((item) => ({
+      ...item,
+      crop_artifact_id: cropArtifact.crop_artifact_id,
+    })));
+    blockers.push(...analysis.blockers);
+    cropImageMetrics.push({
+      crop_artifact_id: cropArtifact.crop_artifact_id,
+      crop_output_path: cropArtifact.crop?.output_path ?? null,
+      image_metrics: analysis.image_metrics,
+    });
+  }
+
+  const dedupedBlockers = [];
+  const seenBlockers = new Set();
+  for (const item of blockers) {
+    const key = `${item.code}:${JSON.stringify(item.evidence ?? {})}`;
+    if (seenBlockers.has(key)) continue;
+    seenBlockers.add(key);
+    dedupedBlockers.push(item);
+  }
+
+  const posture = choosePosture(dedupedBlockers);
+  const acceptedCropArtifactIds = posture === 'visual_qa_accepted'
+    ? cropArtifacts.map((row) => row.crop_artifact_id).filter(Boolean)
+    : [];
+  const availableSignals = availableVlmSignals(candidateRow, cropArtifacts);
+
+  return {
+    schema_version: 'figureasset_wave1_crop_completeness_qa_row.v1',
+    precise_crop_source_map_row_id: candidateRow.precise_crop_source_map_row_id ?? null,
+    packet_id: candidateRow.packet_id ?? null,
+    question_key: candidateRow.question_key ?? sourceMapRow?.question_key ?? null,
+    question_ref: sourceMapRow?.question_ref ?? null,
+    paper_code: candidateRow.paper_code ?? sourceMapRow?.paper_code ?? null,
+    q_number: candidateRow.q_number ?? sourceMapRow?.q_number ?? null,
+    planned_crop_scope: sourceMapRow?.planned_crop_scope ?? null,
+    visual_required_reason: sourceMapRow?.visual_required_reason ?? null,
+    crop_artifact_count: cropArtifacts.length,
+    crop_artifact_ids: cropArtifacts.map((row) => row.crop_artifact_id).filter(Boolean),
+    accepted_crop_artifact_ids: acceptedCropArtifactIds,
+    manual_review_entry_count: manualEntries.length,
+    visual_qa_posture: posture,
+    visual_qa_accepted: posture === 'visual_qa_accepted',
+    qa_evidence: {
+      deterministic_checks: deterministicChecks,
+      available_vlm_signals: availableSignals,
+      crop_image_metrics: cropImageMetrics,
+      source_refs: {
+        precise_crops_manifest: paths.preciseCropsIn,
+        candidate_bbox_proposals: paths.candidateBboxIn,
+        precise_crop_source_map: paths.sourceMapIn,
+      },
+    },
+    blocker_reasons: dedupedBlockers,
+    student_display_eligible_final: false,
+    source_figure_accepted_for_student_display: false,
+    source_visual_receipt_approved: false,
+    rights_display_allowed: false,
+    rights_display_policy_status: 'not_evaluated_out_of_scope_for_issue_1251',
+  };
+}
+
+function buildSummary(rows, preciseCrops) {
+  const postureCounts = Object.fromEntries([...POSTURES].map((posture) => [
+    posture,
+    rows.filter((row) => row.visual_qa_posture === posture).length,
+  ]));
+  const blockerCounts = {};
+  const detectionCounts = {
+    cut_off_axes_or_labels: 0,
+    missing_labels_or_regions: 0,
+    missing_diagram_or_table_region: 0,
+    excessive_whitespace: 0,
+    tiny_crop: 0,
+    wrong_page_crop: 0,
+    multi_figure_ambiguity: 0,
+  };
+  for (const row of rows) {
+    const rowCategories = new Set();
+    for (const item of row.blocker_reasons) {
+      blockerCounts[item.code] = (blockerCounts[item.code] ?? 0) + 1;
+      rowCategories.add(item.category);
+    }
+    if (rowCategories.has('cut_off_axes_or_labels')) {
+      detectionCounts.cut_off_axes_or_labels += 1;
+      detectionCounts.missing_labels_or_regions += 1;
+    }
+    if (rowCategories.has('missing_diagram_or_table_region')) {
+      detectionCounts.missing_diagram_or_table_region += 1;
+      detectionCounts.missing_labels_or_regions += 1;
+    }
+    if (rowCategories.has('excessive_whitespace')) detectionCounts.excessive_whitespace += 1;
+    if (rowCategories.has('tiny_crop')) detectionCounts.tiny_crop += 1;
+    if (rowCategories.has('wrong_page_crop')) detectionCounts.wrong_page_crop += 1;
+    if (rowCategories.has('multi_figure_ambiguity')) detectionCounts.multi_figure_ambiguity += 1;
+  }
+  const acceptedCropArtifactCount = rows.reduce((sum, row) => sum + row.accepted_crop_artifact_ids.length, 0);
+  const deterministicCheckCount = rows.reduce((sum, row) => sum + row.qa_evidence.deterministic_checks.length, 0);
+  const failedDeterministicCheckCount = rows.reduce(
+    (sum, row) => sum + row.qa_evidence.deterministic_checks.filter((item) => item.status === 'fail').length,
+    0,
+  );
+  return {
+    wave1_row_count: rows.length,
+    produced_crop_artifact_count: asArray(preciseCrops.crop_artifacts).length,
+    produced_crop_row_count: new Set(asArray(preciseCrops.crop_artifacts).map((row) => row.precise_crop_source_map_row_id)).size,
+    manual_review_entry_count: asArray(preciseCrops.manual_review_rows).length,
+    visual_qa_accepted_row_count: postureCounts.visual_qa_accepted,
+    needs_human_visual_review_row_count: postureCounts.needs_human_visual_review,
+    needs_manual_crop_row_count: postureCounts.needs_manual_crop,
+    accepted_crop_artifact_count: acceptedCropArtifactCount,
+    blocker_row_count: rows.filter((row) => row.blocker_reasons.length > 0).length,
+    blocker_reason_counts: Object.fromEntries(Object.entries(blockerCounts).sort(([left], [right]) => left.localeCompare(right))),
+    detection_counts: detectionCounts,
+    deterministic_check_count: deterministicCheckCount,
+    failed_deterministic_check_count: failedDeterministicCheckCount,
+    available_vlm_signal_count: rows.reduce((sum, row) => sum + row.qa_evidence.available_vlm_signals.length, 0),
+    external_vlm_call_count: 0,
+    rights_display_allowed_true_count: rows.filter((row) => row.rights_display_allowed === true).length,
+    student_display_eligible_final_true_count: rows.filter((row) => row.student_display_eligible_final === true).length,
+    source_figure_accepted_for_student_display_true_count: rows.filter((row) => row.source_figure_accepted_for_student_display === true).length,
+    source_visual_receipt_approved_true_count: rows.filter((row) => row.source_visual_receipt_approved === true).length,
+  };
+}
+
+function buildFixtures(manifest) {
+  const rows = asArray(manifest.rows);
+  const clear = rows.find((row) => row.visual_qa_posture === 'visual_qa_accepted');
+  const bad = rows.find((row) => row.visual_qa_posture === 'needs_manual_crop');
+  const ambiguous = rows.find((row) => row.visual_qa_posture === 'needs_human_visual_review');
+  return {
+    schema_version: 'figureasset_wave1_crop_completeness_qa_fixtures.v1',
+    generated_at: manifest.generated_at,
+    generated_by: SCRIPT_PATH,
+    issue: ISSUE_NUMBER,
+    source_manifest_path: DEFAULT_PATHS.manifestOut,
+    cases: [
+      {
+        fixture_id: 'clear-pass',
+        expected_posture: 'visual_qa_accepted',
+        row_ref: clear ? {
+          question_key: clear.question_key,
+          precise_crop_source_map_row_id: clear.precise_crop_source_map_row_id,
+          crop_artifact_ids: clear.crop_artifact_ids,
+        } : null,
+        evidence_summary: clear ? {
+          deterministic_check_count: clear.qa_evidence.deterministic_checks.length,
+          available_vlm_signal_count: clear.qa_evidence.available_vlm_signals.length,
+        } : null,
+      },
+      {
+        fixture_id: 'bad-fail',
+        expected_posture: 'needs_manual_crop',
+        row_ref: bad ? {
+          question_key: bad.question_key,
+          precise_crop_source_map_row_id: bad.precise_crop_source_map_row_id,
+          crop_artifact_ids: bad.crop_artifact_ids,
+        } : null,
+        blocker_codes: bad ? bad.blocker_reasons.map((item) => item.code) : [],
+      },
+      {
+        fixture_id: 'ambiguous-review',
+        expected_posture: 'needs_human_visual_review',
+        row_ref: ambiguous ? {
+          question_key: ambiguous.question_key,
+          precise_crop_source_map_row_id: ambiguous.precise_crop_source_map_row_id,
+          crop_artifact_ids: ambiguous.crop_artifact_ids,
+        } : null,
+        blocker_codes: ambiguous ? ambiguous.blocker_reasons.map((item) => item.code) : [],
+      },
+    ],
+  };
+}
+
+function buildReadback({ manifest, validatorResult }) {
+  return [
+    '# FigureAsset Wave 1 Crop Completeness QA Readback',
+    '',
+    `Generated: ${manifest.generated_at}`,
+    '',
+    '## Scope',
+    '',
+    '- Issue: #1251, `[FA-CROP-HVY-07] Run Wave 1 crop completeness QA gate`',
+    '- Parent issue: #1243',
+    '- Depends on: #1250 / FA-CROP-HVY-06',
+    '- External VLM calls performed by this QA gate: 0',
+    '- Visual QA acceptance is crop-completeness QA only; it is not rights/display permission.',
+    '',
+    '## Outputs',
+    '',
+    `- QA manifest: \`${DEFAULT_PATHS.manifestOut}\``,
+    `- QA readback: \`${DEFAULT_PATHS.readbackOut}\``,
+    `- QA fixtures: \`${DEFAULT_PATHS.fixturesOut}\``,
+    `- Validator result: \`${DEFAULT_PATHS.validatorOut}\``,
+    '',
+    '## Counts',
+    '',
+    `- Wave 1 rows: ${manifest.summary.wave1_row_count}`,
+    `- Produced crop artifacts checked: ${manifest.summary.produced_crop_artifact_count}`,
+    `- Visual QA accepted rows: ${manifest.summary.visual_qa_accepted_row_count}`,
+    `- Needs human visual review rows: ${manifest.summary.needs_human_visual_review_row_count}`,
+    `- Needs manual crop rows: ${manifest.summary.needs_manual_crop_row_count}`,
+    `- Blocker rows: ${manifest.summary.blocker_row_count}`,
+    `- Accepted crop artifacts: ${manifest.summary.accepted_crop_artifact_count}`,
+    `- Deterministic checks: ${manifest.summary.deterministic_check_count}`,
+    `- Failed deterministic checks: ${manifest.summary.failed_deterministic_check_count}`,
+    `- Available VLM QA signals consumed: ${manifest.summary.available_vlm_signal_count}`,
+    '',
+    '## Detection Counts',
+    '',
+    `- Cut-off axes/labels: ${manifest.summary.detection_counts.cut_off_axes_or_labels}`,
+    `- Missing labels/regions: ${manifest.summary.detection_counts.missing_labels_or_regions}`,
+    `- Missing diagram/table regions: ${manifest.summary.detection_counts.missing_diagram_or_table_region}`,
+    `- Excessive whitespace: ${manifest.summary.detection_counts.excessive_whitespace}`,
+    `- Tiny crops: ${manifest.summary.detection_counts.tiny_crop}`,
+    `- Wrong-page crops: ${manifest.summary.detection_counts.wrong_page_crop}`,
+    `- Multi-figure ambiguity: ${manifest.summary.detection_counts.multi_figure_ambiguity}`,
+    '',
+    '## Boundary',
+    '',
+    '- Rights/display fields remain false.',
+    '- SourceVisualReceipt approval remains false.',
+    '- Student-display eligibility remains false.',
+    '- No Supabase mutation, storage upload, HTTP write probe, or external model call is performed.',
+    '',
+    '## Validation',
+    '',
+    `- Status: ${validatorResult.summary.validation_status}`,
+    `- Checks: ${validatorResult.summary.check_count}`,
+    `- Failed checks: ${validatorResult.summary.failed_check_count}`,
+  ].join('\n');
+}
+
+function buildValidator({ manifest, fixtures, readback, generatedAt }) {
+  const rows = asArray(manifest.rows);
+  const acceptedRows = rows.filter((row) => row.visual_qa_posture === 'visual_qa_accepted');
+  const nonAcceptedRows = rows.filter((row) => row.visual_qa_posture !== 'visual_qa_accepted');
+  const allowedPostures = rows.every((row) => POSTURES.has(row.visual_qa_posture));
+  const noRightsOrDisplayClaims = rows.every((row) => (
+    row.student_display_eligible_final === false
+    && row.source_figure_accepted_for_student_display === false
+    && row.source_visual_receipt_approved === false
+    && row.rights_display_allowed === false
+  ));
+  const acceptedHaveEvidence = acceptedRows.every((row) => (
+    row.visual_qa_accepted === true
+    && row.accepted_crop_artifact_ids.length > 0
+    && row.blocker_reasons.length === 0
+    && row.qa_evidence.deterministic_checks.some((item) => item.id === 'crop_file_exists' && item.status === 'pass')
+    && row.qa_evidence.deterministic_checks.some((item) => item.id === 'crop_image_nonblank' && item.status === 'pass')
+    && row.qa_evidence.available_vlm_signals.some((item) => item.signal === 'completeness_status' && item.value === 'complete_visual_candidate')
+  ));
+  const failedRowsActionable = nonAcceptedRows.every((row) => (
+    row.visual_qa_accepted === false
+    && row.blocker_reasons.length > 0
+    && row.blocker_reasons.every((item) => item.code && item.action && item.severity)
+  ));
+  const requiredFixtures = new Set(['clear-pass', 'bad-fail', 'ambiguous-review']);
+  const fixtureIds = new Set(asArray(fixtures.cases).map((item) => item.fixture_id));
+  const fixturesPresent = [...requiredFixtures].every((item) => fixtureIds.has(item));
+  const checks = [
+    check('schema_version', manifest.schema_version === 'figureasset_wave1_crop_completeness_qa.v1' ? 'pass' : 'fail', {
+      schema_version: manifest.schema_version,
+    }),
+    check('row_count_matches_summary', rows.length === manifest.summary.wave1_row_count ? 'pass' : 'fail', {
+      row_count: rows.length,
+      summary_row_count: manifest.summary.wave1_row_count,
+    }),
+    check('allowed_visual_qa_postures', allowedPostures ? 'pass' : 'fail'),
+    check('accepted_rows_have_explicit_qa_evidence', acceptedHaveEvidence ? 'pass' : 'fail', {
+      accepted_row_count: acceptedRows.length,
+    }),
+    check('nonaccepted_rows_have_actionable_blockers', failedRowsActionable ? 'pass' : 'fail', {
+      nonaccepted_row_count: nonAcceptedRows.length,
+    }),
+    check('no_external_vlm_calls', manifest.boundary?.external_vlm_calls_performed === 0 ? 'pass' : 'fail', {
+      external_vlm_calls_performed: manifest.boundary?.external_vlm_calls_performed,
+    }),
+    check('rights_display_fields_remain_false', noRightsOrDisplayClaims ? 'pass' : 'fail', {
+      rights_display_allowed_true_count: manifest.summary.rights_display_allowed_true_count,
+      student_display_eligible_final_true_count: manifest.summary.student_display_eligible_final_true_count,
+      source_figure_accepted_for_student_display_true_count: manifest.summary.source_figure_accepted_for_student_display_true_count,
+      source_visual_receipt_approved_true_count: manifest.summary.source_visual_receipt_approved_true_count,
+    }),
+    check('fixtures_cover_required_cases', fixturesPresent ? 'pass' : 'fail', {
+      fixture_ids: [...fixtureIds].sort(),
+    }),
+    check('readback_counts_present', (
+      typeof readback === 'string'
+      && readback.includes('Visual QA accepted rows')
+      && readback.includes('Needs manual crop rows')
+      && readback.includes('Needs human visual review rows')
+    ) ? 'pass' : 'fail'),
+  ];
+  const failedChecks = checks.filter((item) => item.status !== 'pass');
+  return {
+    schema_version: 'figureasset_wave1_crop_completeness_qa_validator.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_PATH,
+    summary: {
+      validation_status: failedChecks.length === 0 ? 'pass' : 'fail',
+      check_count: checks.length,
+      failed_check_count: failedChecks.length,
+      wave1_row_count: manifest.summary.wave1_row_count,
+      visual_qa_accepted_row_count: manifest.summary.visual_qa_accepted_row_count,
+      needs_human_visual_review_row_count: manifest.summary.needs_human_visual_review_row_count,
+      needs_manual_crop_row_count: manifest.summary.needs_manual_crop_row_count,
+    },
+    checks,
+  };
+}

